pm.test("[Data] Payload dashboard lengkap (schedule & top_pick_rate)", function () {
    var j = pm.response.json();
    pm.expect(j.data).to.be.an('object');
    pm.expect(j.data.schedule).to.be.an('array');
    pm.expect(j.data.top_pick_rate).to.be.an('array');
});

